CREATE     PROCEDURE [synapse_fo].[usp_Insert_BANKACCOUNTTRANS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:39
	Description: Insert stored procedure for BANKACCOUNTTRANS from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[BANKACCOUNTTRANS]
	(
		[ACCOUNTID],
		[ACCOUNTINGCURRENCYAMOUNTCORRECT_RU],
		[ACCOUNTSTATEMENT],
		[ACCOUNTSTATEMENTDATE],
		[ACKNOWLEDGEMENTDATE],
		[AMOUNTCORRECT],
		[AMOUNTCUR],
		[AMOUNTMST],
		[AMOUNTREPORTINGCURRENCY],
		[BANKPAYMENTREGISTRATIONNUM_LV],
		[BANKTRANSAMOUNTCUR],
		[BANKTRANSCURRENCYCODE],
		[BANKTRANSTYPE],
		[CANCEL],
		[CANCELPENDING],
		[CENTRALBANKPURPOSECODE_LV],
		[CENTRALBANKPURPOSETEXT_LV],
		[CHEQUENUM],
		[CLEAREDDATE],
		[CORRESPONDENTCOUNTRY_LV],
		[CREATEDBY],
		[CREATEDDATETIME],
		[CURRENCYCODE],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DEFAULTDIMENSION],
		[DEPOSITNUM],
		[FileName],
		[INCLUDED],
		[ISSUMMARIZATION],
		[LastProcessedChange_DateTime],
		[LEDGERDIMENSION],
		[LEDGERTRANSTYPE],
		[LSN],
		[MANUAL],
		[MODIFIEDBY],
		[MODIFIEDDATETIME],
		[PARTITION],
		[PAYMENTMODE],
		[PAYMREFERENCE],
		[REASONREFRECID],
		[RECID],
		[RECONCILED],
		[RECVERSION],
		[REFRECID_RU],
		[REPORTINGCURRENCYAMOUNT_RU],
		[REPORTINGCURRENCYAMOUNTCORRECT_RU],
		[SKS_BR_ALREADYMARKED],
		[SKS_BR_BANKTRANRECID],
		[SKS_BR_INTERMMATCH],
		[SKS_BR_ISSELECTED],
		[SKS_BR_MANUALRECONCILIATIONID],
		[SKS_BR_MARKEDFROMRECONCILESTATEMENT],
		[SKS_CCR_ALREADYMARKED],
		[SKS_CCR_BANKTRANRECID],
		[SKS_CCR_INTERMMATCH],
		[SKS_CCR_ISCURRENCYADJUSTMENT],
		[SKS_CCR_ISPARTOFREVERSAL],
		[SKS_CCR_ISSELECTED],
		[SKS_CCR_MANUALRECONCILIATIONID],
		[SKS_EFTAP_INBOUNDREFNUM],
		[SKS_IHB_APPROPRIATIONCALCULATED],
		[SKS_IHB_INTERESTCALCULATED],
		[SKS_IHB_STATEMENTDATE],
		[SKS_IHB_STATEMENTNUMBER],
		[SKS_IHB_VALUEDATE],
		[SOURCERECID],
		[SOURCETABLEID],
		[SUMMARIZATIONID],
		[SysRowId],
		[TAXGROUP],
		[TAXITEMGROUP],
		[TRANSDATE],
		[TXT],
		[VOUCHER]
	)
	SELECT 
		stg.[ACCOUNTID],
		stg.[ACCOUNTINGCURRENCYAMOUNTCORRECT_RU],
		stg.[ACCOUNTSTATEMENT],
		stg.[ACCOUNTSTATEMENTDATE],
		stg.[ACKNOWLEDGEMENTDATE],
		stg.[AMOUNTCORRECT],
		stg.[AMOUNTCUR],
		stg.[AMOUNTMST],
		stg.[AMOUNTREPORTINGCURRENCY],
		stg.[BANKPAYMENTREGISTRATIONNUM_LV],
		stg.[BANKTRANSAMOUNTCUR],
		stg.[BANKTRANSCURRENCYCODE],
		stg.[BANKTRANSTYPE],
		stg.[CANCEL],
		stg.[CANCELPENDING],
		stg.[CENTRALBANKPURPOSECODE_LV],
		stg.[CENTRALBANKPURPOSETEXT_LV],
		stg.[CHEQUENUM],
		stg.[CLEAREDDATE],
		stg.[CORRESPONDENTCOUNTRY_LV],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[CURRENCYCODE],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DEFAULTDIMENSION],
		stg.[DEPOSITNUM],
		stg.[FileName],
		stg.[INCLUDED],
		stg.[ISSUMMARIZATION],
		stg.[LastProcessedChange_DateTime],
		stg.[LEDGERDIMENSION],
		stg.[LEDGERTRANSTYPE],
		stg.[LSN],
		stg.[MANUAL],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[PARTITION],
		stg.[PAYMENTMODE],
		stg.[PAYMREFERENCE],
		stg.[REASONREFRECID],
		stg.[RECID],
		stg.[RECONCILED],
		stg.[RECVERSION],
		stg.[REFRECID_RU],
		stg.[REPORTINGCURRENCYAMOUNT_RU],
		stg.[REPORTINGCURRENCYAMOUNTCORRECT_RU],
		stg.[SKS_BR_ALREADYMARKED],
		stg.[SKS_BR_BANKTRANRECID],
		stg.[SKS_BR_INTERMMATCH],
		stg.[SKS_BR_ISSELECTED],
		stg.[SKS_BR_MANUALRECONCILIATIONID],
		stg.[SKS_BR_MARKEDFROMRECONCILESTATEMENT],
		stg.[SKS_CCR_ALREADYMARKED],
		stg.[SKS_CCR_BANKTRANRECID],
		stg.[SKS_CCR_INTERMMATCH],
		stg.[SKS_CCR_ISCURRENCYADJUSTMENT],
		stg.[SKS_CCR_ISPARTOFREVERSAL],
		stg.[SKS_CCR_ISSELECTED],
		stg.[SKS_CCR_MANUALRECONCILIATIONID],
		stg.[SKS_EFTAP_INBOUNDREFNUM],
		stg.[SKS_IHB_APPROPRIATIONCALCULATED],
		stg.[SKS_IHB_INTERESTCALCULATED],
		stg.[SKS_IHB_STATEMENTDATE],
		stg.[SKS_IHB_STATEMENTNUMBER],
		stg.[SKS_IHB_VALUEDATE],
		stg.[SOURCERECID],
		stg.[SOURCETABLEID],
		stg.[SUMMARIZATIONID],
		stg.[SysRowId],
		stg.[TAXGROUP],
		stg.[TAXITEMGROUP],
		stg.[TRANSDATE],
		stg.[TXT],
		stg.[VOUCHER]	
	FROM [staging_fo].[BANKACCOUNTTRANS] stg
		LEFT JOIN [synapse_fo].[BANKACCOUNTTRANS] tgt
			ON stg.[AccountId] = tgt.[AccountId] 
			AND stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
			AND stg.[RECID] = tgt.[RECID] 
			AND stg.[TransDate] = tgt.[TransDate] 
		
	WHERE tgt.[RECID] IS NULL
END
